(7228847, 1116378, 58634, '<td valign="top">Love, love, love the fog and the golden autumn leaves. Beautiful!</td>', 'Love, love, love the fog and the golden autumn leaves. Beautiful!', '2014-06-14 20:17:55.000000', NULL, 1),
(7228848, 1116929, 58634, '<td valign="top">Absolutely lovely image. It may have benefited <i>slightly</i> from a bit more contrast, but really, it''s beautiful the way it is, too.</td>', 'Absolutely lovely image. It may have benefited slightly from a bit more contrast, but really, it''s beautiful the way it is, too.', '2014-06-14 20:18:43.000000', NULL, 1),
(7228849, 1116047, 58634, '<td valign="top">I really like the perfect, sharp focus of the mud.</td>', 'I really like the perfect, sharp focus of the mud.', '2014-06-14 20:19:08.000000', NULL, 1),
(7228850, 1116209, 58634, '<td valign="top">Awesome title! I love this! So contrasted that it almost looks B&amp;W, yet certain colors stand out beatifully. I also enjoy how soft the feathers look.</td>', 'Awesome title! I love this! So contrasted that it almost looks B&W, yet certain colors stand out beatifully. I also enjoy how soft the feathers look.', '2014-06-14 20:20:03.000000', NULL, 1),
(7228851, 1116986, 58634, '<td valign="top">The scene captured here is excellent. However I would''ve preferred a contrast bump just to make the moment more dramatic and pop a bit more.</td>', 'The scene captured here is excellent. However I would''ve preferred a contrast bump just to make the moment more dramatic and pop a bit more.', '2014-06-14 20:21:18.000000', NULL, 1),
(7228852, 1116848, 58634, '<td valign="top">FANTASTIC image. Extra points for the border creativity. Simply excellent.</td>', 'FANTASTIC image. Extra points for the border creativity. Simply excellent.', '2014-06-14 20:21:51.000000', NULL, 1),
(7228853, 1116365, 58634, '<td valign="top">So fluffy and precious. Can I hold them, pretty please!?</td>', 'So fluffy and precious. Can I hold them, pretty please!?', '2014-06-14 20:22:43.000000', NULL, 1),
