(7228855, 1116931, 58634, '<td valign="top">I like your play on words for the title. I almost wish this was either cropped less, or cropped more though.</td>', 'I like your play on words for the title. I almost wish this was either cropped less, or cropped more though.', '2014-06-14 20:27:24.000000', NULL, 1),
(7228856, 1116866, 58634, '<td valign="top">Nothing quite like a simplistic approach. I quite enjoy the negative space here. It differs from the typical or "obvious" choice when it comes to negative space. I also like how rough the boots look... I guess that''s why they''re old :P</td>', 'Nothing quite like a simplistic approach. I quite enjoy the negative space here. It differs from the typical or "obvious" choice when it comes to negative space. I also like how rough the boots look... I guess that''s why they''re old :P', '2014-06-14 20:28:42.000000', NULL, 1),
(7228857, 1116725, 58634, '<td valign="top">Beautifully compelling photograph. I like the stormy clouds in the background.</td>', 'Beautifully compelling photograph. I like the stormy clouds in the background.', '2014-06-14 20:30:14.000000', NULL, 1),
(7228858, 1115996, 58634, '<td valign="top">Beautiful textures, shapes and shadows. Excellent choice with the B&amp;W with the exception of the chair.</td>', 'Beautiful textures, shapes and shadows. Excellent choice with the B&W with the exception of the chair.', '2014-06-14 20:31:13.000000', NULL, 1),
(7228859, 1116747, 58634, '<td valign="top">I LOVE THIS. Dreamy, velvety and exquisite. Both scary, yet peaceful and comforting. Wonderful image.</td>', 'I LOVE THIS. Dreamy, velvety and exquisite. Both scary, yet peaceful and comforting. Wonderful image.', '2014-06-14 20:32:38.000000', NULL, 1),
