(7228865, 1117026, 58634, '<td valign="top">Beautiful, peaceful village.</td>', 'Beautiful, peaceful village.', '2014-06-14 20:42:07.000000', NULL, 1),
(7228866, 1117031, 58634, '<td valign="top">I think this would be an AMAZING SHOT if it wasn''t for the head on the left!! Maybe it would''ve been better to crop off most of the head and/or clone it out if necessary? Other than that, the image is excellent but that''s something I can''t get past &gt;.&lt;</td>', 'I think this would be an AMAZING SHOT if it wasn''t for the head on the left!! Maybe it would''ve been better to crop off most of the head and/or clone it out if necessary? Other than that, the image is excellent but that''s something I can''t get past >.<', '2014-06-14 20:43:32.000000', NULL, 1),
(7228867, 1115832, 58634, '<td valign="top">I quite enjoy the colorful scene. It looks serene.</td>', 'I quite enjoy the colorful scene. It looks serene.', '2014-06-14 20:44:12.000000', NULL, 1),
(7228868, 1116652, 58634, '<td valign="top">Very dramatic image! The sky looks electric and the house looks spooky!</td>', 'Very dramatic image! The sky looks electric and the house looks spooky!', '2014-06-14 20:44:42.000000', NULL, 1),
(7228869, 1115836, 58634, '<td valign="top">I feel as if the title doesn''t quite fit this because it looks neither stormy, nor like a (typical) sunset. However, the image itself is very nice and I like how you''ve captured the water meeting the rocks in an almost peaceful manner.</td>', 'I feel as if the title doesn''t quite fit this because it looks neither stormy, nor like a (typical) sunset. However, the image itself is very nice and I like how you''ve captured the water meeting the rocks in an almost peaceful manner.', '2014-06-14 20:45:58.000000', NULL, 1),
(7228870, 1117134, 58634, '<td valign="top">I like how you can tell that the sun is just about to set, and due to that not all the houses have turned their lights on just yet. Gives this a very human quality that I like.</td>', 'I like how you can tell that the sun is just about to set, and due to that not all the houses have turned their lights on just yet. Gives this a very human quality that I like.', '2014-06-14 20:47:07.000000', NULL, 1),
(7228871, 1116262, 58634, '<td valign="top">Double rainbow at it''s finest! Beatiful colors all around! What a great shot! Every time I try to shoot a rainbow it''s all dark, yet you''ve managed such a cheerful scene! Kudos.</td>', 'Double rainbow at it''s finest! Beatiful colors all around! What a great shot! Every time I try to shoot a rainbow it''s all dark, yet you''ve managed such a cheerful scene! Kudos.', '2014-06-14 20:50:41.000000', NULL, 1),
