(7228907, 1116992, 73056, '<td valign="top">Beautiful reflections.</td>', 'Beautiful reflections.', '2014-06-14 22:08:56.000000', NULL, 1),
(7228909, 1116423, 128323, '<td valign="top">Wow.  This is such an inspiring image.  It should be a painting, but it still retains a photographic quality to it.  Everything about it is perfect.  The light, the form, the mood, everything.  This is the kind of photo that inspires others to become photographers.  <br/> <br/>If this isn''t a blue ribbon, it''s only because of low votes for the nudity.  You''ve created a masterpiece.  One of the finest photos to grace this site.  Thank you for sharing it.</td>', 'Wow.  This is such an inspiring image.  It should be a painting, but it still retains a photographic quality to it.  Everything about it is perfect.  The light, the form, the mood, everything.  This is the kind of photo that inspires others to become photographers.   If this isn''t a blue ribbon, it''s only because of low votes for the nudity.  You''ve created a masterpiece.  One of the finest photos to grace this site.  Thank you for sharing it.', '2014-06-14 22:09:32.000000', NULL, 1),
(7228910, 1116988, 73056, '<td valign="top">What great timing! Birds, lighting, clouds.  What more could you ask for!</td>', 'What great timing! Birds, lighting, clouds.  What more could you ask for!', '2014-06-14 22:09:55.000000', NULL, 1);
