(7229462, 1116800, 58634, '<td valign="top">So dreamy! I''m usually not a big fan of centered subjects, but in this case, it works! Very lovely.</td>', 'So dreamy! I''m usually not a big fan of centered subjects, but in this case, it works! Very lovely.', '2014-06-16 18:07:05.000000', NULL, 1),
(7229463, 1116333, 58634, '<td valign="top">Great rough looking rocks, especially agains the smooth water. Good perspective to really make the lighthouse the center of attention despite the fact that it''s "far away".</td>', 'Great rough looking rocks, especially agains the smooth water. Good perspective to really make the lighthouse the center of attention despite the fact that it''s "far away".', '2014-06-16 18:08:00.000000', NULL, 1),
(7229465, 1116974, 58634, '<td valign="top">Somewhat depressing... I love the intrigued child in the corner.</td>', 'Somewhat depressing... I love the intrigued child in the corner.', '2014-06-16 18:09:34.000000', NULL, 1),
(7229467, 1116778, 58634, '<td valign="top">Beautifully curvy shadows. It makes this flow in a very elegant way.</td>', 'Beautifully curvy shadows. It makes this flow in a very elegant way.', '2014-06-16 18:10:15.000000', NULL, 1),
(7229468, 1117073, 19959, '<td valign="top">The clouds really compliment the twisted tree... great capture... good luck</td>', 'The clouds really compliment the twisted tree... great capture... good luck', '2014-06-16 18:16:44.000000', NULL, 1),
(7229469, 1115864, 19959, '<td valign="top">Great shot... I''ve been to the spot a few times and this is well crafted and perfectly timed.<br/>The golden glow in the sky compliments the strong blues. <br/> <br/>Golden light - Check<br/>Wheel Stopped - Check<br/>Good illumination on Wheel - Check<br/>Wave filling foreground - Check<br/>Wave creating interesting lead in line to subject - Check</td>', 'Great shot... I''ve been to the spot a few times and this is well crafted and perfectly timed.The golden glow in the sky compliments the strong blues.  Golden light - CheckWheel Stopped - CheckGood illumination on Wheel - CheckWave filling foreground - CheckWave creating interesting lead in line to subject - Check', '2014-06-16 18:21:20.000000', NULL, 1),
(7229470, 1116378, 19959, '<td valign="top">beautiful</td>', 'beautiful', '2014-06-16 18:21:50.000000', NULL, 1),
