(7229956, 1116098, 58634, '<td valign="top">I like your choice of shallow DOF, but find the overall image pretty flat.</td>', 'I like your choice of shallow DOF, but find the overall image pretty flat.', '2014-06-17 17:36:23.000000', NULL, 1),
