(7230670, 1116948, 16106, '<td valign="top">I thought this was a lovely and complete image with subtle colors and complex architecture, understated and elegant with a great use of a diagonal line to organize the elements. MUA.</td>', 'I thought this was a lovely and complete image with subtle colors and complex architecture, understated and elegant with a great use of a diagonal line to organize the elements. MUA.', '2014-06-18 18:26:42.000000', NULL, 0),
(7230671, 1116300, 16106, '<td valign="top">Congratulations on being the lowest scoring of my high scoring images. The MUA of the MUAs. The reflections on the street alone are worth getting lost in, lovely shot, but it might take more looking than some are interested in giving.<br/><br/><i>Message edited by author 2014-06-18 17:31:20.</i></td>', 'Congratulations on being the lowest scoring of my high scoring images. The MUA of the MUAs. The reflections on the street alone are worth getting lost in, lovely shot, but it might take more looking than some are interested in giving.', '2014-06-18 18:30:52.000000', '2014-06-18 18:31:20.000000', 0),
